# Surah Yusuf (chapter 12) — part 5: ayat 41-50 (IDs 1637-1646)
SURAH = 12

ENTRIES = {
1637: (
"اے میرے جیل — کے ساتھ — تم میں سے ایک — اپنے رب — کو شراب — پلائے گا — اور — دوسرا — سولی — پر چڑھایا جائے گا — پس — پرندے اس کے سر — سے کھائیں گے — جس معاملے — کے بارے میں — تم — پُہاچ — جواب مانگ رہے ہو — وہ — طے — ہو گیا",
"""۱۔ یوسفؑ — دونوں ساتھیوں — کی تعبیر — جتنے — حساب — سے دیتے ہیں۔
۲۔ ’’يَا صَاحِبَيِ السِّجْنِ أَمَّا أَحَدُكُمَا فَيَسْقِي رَبَّهُ خَمْرًا وَأَمَّا الْآخَرُ فَيُصْلَبُ فَتَأْكُلُ الطَّيْرُ مِن رَّأْسِهِ قُضِيَ الْأَمْرُ الَّذِي فِيهِ تَسْتَفْتِيَانِ‘‘ — اے میرے جیل — کے ساتھ — تم میں سے ایک — اپنے رب — کو شراب — پلائے گا — اور — دوسرا — سولی — پر چڑھایا جائے گا — پس — پرندے اس کے سر — سے کھائیں گے — جس معاملے — کے بارے میں — تم — پُہاچ — جواب مانگ رہے ہو — وہ — طے — ہو گیا — یعنی اے میرے جیل کے ساتھ — تم میں سے ایک — اپنے مالک کو — شراب پلائے گا — اور — دوسرا — سولی — دیا جائے گا — اور — پرندے — اس کے — سر — سے — کھائیں گے — جس کے بارے میں — تم دونوں — پوچھ رہے تھے — وہ — طے ہو — گیا۔
۳۔ عملی سبق: اللہ — بعض اوقات — خواب — میں — نتائج — بتا دیتا ہے؛ دل — پر — یقین — رکھیں۔"""
),
1638: (
"اور — اس — شخص — سے — کہا — جس — کے بارے میں — وہ سمجھتا تھا — کہ — وہ — بچ جائے گا — ان دو میں سے — اپنے رب کے پاس — میرا — ذکر — کرو — پس — شیطان نے — اس — کو — اپنے رب کے پاس — ذکر — بھلا دیا — پس — وہ — جیل — میں — کئی — سال — رہا",
"""۱۔ یوسفؑ — عزیز سے کہلواتے ہیں — شیطان نے پیغام — بھلا دیا؛ صبر — رکھا۔
۲۔ ’’وَقَالَ لِلَّذِي ظَنَّ أَنَّهُ نَاجٍ مِّنْهُمَا اذْكُرْنِي عِندَ رَبِّكَ فَأَنسَاهُ الشَّيْطَانُ ذِكْرَ رَبِّهِ فَلَبِثَ فِي السِّجْنِ بِضْعَ سِنِينَ‘‘ — اور — اس — شخص — سے — کہا — جس — کے بارے میں — وہ سمجھتا تھا — کہ — وہ — بچ جائے گا — ان دو میں سے — اپنے رب کے پاس — میرا — ذکر — کرو — پس — شیطان نے — اس — کو — اپنے رب کے پاس — ذکر — بھلا دیا — پس — وہ — جیل — میں — کئی — سال — رہا — یعنی یوسفؑ — نے اس — سے — جس — کے بارے — میں — وہ سمجھتا تھا کہ وہ — بچ جائے گا — کہا — اپنے رب — کے پاس — میرا — ذکر — کرو — پس — شیطان نے — اس کو — اپنے رب کے پاس — ذکر — بھلا دیا — پس وہ — جیل — میں کئی سال — رہا۔
۳۔ عملی سبق: توسل — کوئی — حد تک — رازق — ہے؛ حقیقت — اللہ — کے پاس — ہے؛ صبر — کرو۔"""
),
1639: (
"اور — بادشاہ — نے — کہا — بے شک — میں — دیکھتا ہوں — سات — موٹی — گائیں — کہ — انہیں — سات — دبلی گائیں — کھا رہی ہیں — اور — سات — سبز — بالیاں — اور دوسری — سوکھی ہوئی — اے اہلِ مجلس — مجھے — میرے خواب — کی تعبیر — بتاؤ — اگر — تم — خواب — کی تعبیر — کرتے ہو",
"""۱۔ بادشاہ — کا خواب — سات موٹی گائیں، سات دبلی، سات سبز بالیاں اور سات سوکھی۔
۲۔ ’’وَقَالَ الْمَلِكُ إِنِّي أَرَىٰ سَبْعَ بَقَرَاتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنبُلَاتٍ خُضْرٍ وَأُخَرَ يَابِسَاتٍ يَا أَيُّهَا الْمَلَأُ أَفْتُونِي فِي رُؤْيَايَ إِن كُنتُمْ لِلرُّؤْيَا تَعْبُرُونَ‘‘ — اور — بادشاہ — نے — کہا — بے شک — میں — دیکھتا ہوں — سات — موٹی — گائیں — کہ — انہیں — سات — دبلی گائیں — کھا رہی ہیں — اور — سات — سبز — بالیاں — اور دوسری — سوکھی ہوئی — اے اہلِ مجلس — مجھے — میرے خواب — کی تعبیر — بتاؤ — اگر — تم — خواب — کی تعبیر — کرتے ہو — یعنی بادشاہ نے — کہا — میں دیکھتا ہوں — سات — موٹی — گائیں — انہیں سات — دبلی گائیں — کھا رہی ہیں — اور سات — سبز — بالیاں — اور دوسری — سوکھی ہوئی — اے اہلِ مجلس — مجھے میرے خواب — کی تعبیر — بتاؤ — اگر تم خواب — کی تعبیر — کرتے ہو۔
۳۔ عملی سبق: خواب — بھی — اللہ کی نشانیاں — ہیں؛ علماء — سے پوچھو۔"""
),
1640: (
"انہوں نے — کہا — بکھری — خواب — ہیں — اور — ہم — بکھرے خوابوں — کی تعبیر — جاننے والے — نہیں",
"""۱۔ درباریوں — کی — لا علمی — بکھرے — خواب۔
۲۔ ’’قَالُوا أَضْغَاثُ أَحْلَامٍ وَمَا نَحْنُ بِتَأْوِيلِ الْأَحْلَامِ بِعَالِمِينَ‘‘ — انہوں نے — کہا — بکھری — خواب — ہیں — اور — ہم — بکھرے خوابوں — کی تعبیر — جاننے والے — نہیں — یعنی انہوں — نے کہا — یہ — بکھرے — ہوئے خواب — ہیں — اور ہم — بکھرے — ہوئے خوابوں کی تعبیر — جاننے — والے — نہیں۔
۳۔ عملی سبق: جس — چیز — کا — علم — نہ ہو — اس کا انکار نہ کرو؛ اہلِ علم — سے پوچھو۔"""
),
1641: (
"اور — ان — میں سے — جس — نے — نجات — پائی — اور اس — کے بعد — یاد — آیا — دیر کے بعد — اس نے کہا — میں — تمہیں — اس — کی — تعبیر — بتا سکتا ہوں — پس — مجھے — بھیجو",
"""۱۔ جیل — سے نجات پانے والا — یوسفؑ — کو — یاد — کرتا ہے — تعبیر کی پیشکش۔
۲۔ ’’وَقَالَ الَّذِي نَجَا مِنْهُمَا وَادَّكَرَ بَعْدَ أُمَّۃٍ أَنَا أُنَبِّئُكُم بِتَأْوِيلِهِ فَأَرْسِلُونِ‘‘ — اور — ان — میں سے — جس — نے — نجات — پائی — اور اس — کے بعد — یاد — آیا — دیر کے بعد — اس نے کہا — میں — تمہیں — اس — کی — تعبیر — بتا سکتا ہوں — پس — مجھے — بھیجو — یعنی دونوں — میں — سے — جس نے — نجات پائی — اور — اس — کے بعد — دیر — کے بعد — اسے — یاد آیا — اس نے — کہا — میں — تمہیں — اس — کی تعبیر — بتا سکتا — ہوں — پس — مجھے — بھیجو۔
۳۔ عملی سبق: اچھے لوگ — یاد — وہی — رکھتے ہیں؛ ان کا — تعلق برقرار — رکھیں۔"""
),
1642: (
"اے — یوسفؑ — اے صدیق — ہمیں — اس — بارے میں — فتویٰ — دو — سات موٹی گائیں — تیرے — سامنے — سات دبلی گائیں — اور — سات سبز بالیاں — اور دوسری سوکھی — تاکہ — میں — لوگوں — کے پاس واپس — جاؤں — شاید — وہ — جانیں",
"""۱۔ جیل میں — پیغام — یوسف — سے — بادشاہ — کے خواب کی تعبیر۔
۲۔ ’’يُوسُفُ أَيُّهَا الصِّدِّيقُ أَفْتِنَا فِي سَبْعِ بَقَرَاتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعِ سُنبُلَاتٍ خُضْرٍ وَأُخَرَ يَابِسَاتٍ لَّعَلِّي أَرْجِعُ إِلَى النَّاسِ لَعَلَّهُمْ يَعْلَمُونَ‘‘ — اے — یوسفؑ — اے صدیق — ہمیں — اس — بارے میں — فتویٰ — دو — سات موٹی گائیں — تیرے — سامنے — سات دبلی گائیں — اور — سات سبز بالیاں — اور دوسری سوکھی — تاکہ — میں — لوگوں — کے پاس واپس — جاؤں — شاید — وہ — جانیں — یعنی اے — یوسف — اے صدیق — ہمیں — فتویٰ دو — سات — موٹی — گائیں — کہ — انہیں — سات دبلی گائیں — کھا رہی ہیں — اور — سات — سبز — بالیاں — اور دوسری سوکھی ہوئی — تاکہ — میں — لوگوں — کے پاس واپس — جاؤں — شاید — وہ — جانیں۔
۳۔ عملی سبق: یوسفؑ کی — صدیقی — مشہور تھی؛ صادق — لوگوں — سے فائدہ — اٹھاؤ۔"""
),
1643: (
"انہوں نے — کہا — تم — سات سال تک — لگاتار — بوؤ گے — پس — جو — تم نے — کاٹا — اس — کو — اس — کی بالیوں — میں — چھوڑ دو — سوائے — تھوڑہ — سا — جو — تم — کھاؤ",
"""۱۔ سات سال — کی پیداوار — ذخیرہ کرنے کی ہدایت۔
۲۔ ’’قَالَ تَزْرَعُونَ سَبْعَ سِنِينَ دَأَبًا فَمَا حَصَدتُّمْ فَذَرُوهُ فِي سُنبُلِهِ إِلَّا قَلِيلًا مِّمَّا تَأْكُلُونَ‘‘ — انہوں نے — کہا — تم — سات سال تک — لگاتار — بوؤ گے — پس — جو — تم نے — کاٹا — اس — کو — اس — کی بالیوں — میں — چھوڑ دو — سوائے — تھوڑہ — سا — جو — تم — کھاؤ — یعنی یوسفؑ — نے کہا — تم — سات سال تک — لگاتار — بوؤ — گے — پس — جو — تم — نے — کاٹا — اس — کو — اس کی بالیوں — میں — چھوڑ دو — سوائے — تھوڑا — سا — جو — تم — کھاؤ۔
۳۔ عملی سبق: منصوبہ بندی — ہے — کامیابی — کی — کلید — ہے۔"""
),
1644: (
"پھر — اس کے بعد — سات — سخت — سال — آئیں گے — جو — وہ — کھا جائیں گے — جو — تم — نے — ان — کے لیے — ذخیرہ کیا — سوائے — اس کے — جسے — تم — محفوظ — رکھو",
"""۱۔ سات — قحط سالوں — کی پیشن گوئی — ذخیرہ اندوزی کی ضرورت۔
۲۔ ’’ثُمَّ يَأْتِي مِن بَعْدِ ذَٰلِكَ سَبْعٌ شِدَادٌ يَأْكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ إِلَّا قَلِيلًا مِّمَّا تُحْصِنُونَ‘‘ — پھر — اس کے بعد — سات — سخت — سال — آئیں گے — جو — وہ — کھا جائیں گے — جو — تم — نے — ان — کے لیے — ذخیرہ کیا — سوائے — اس کے — جسے — تم — محفوظ — رکھو — یعنی پھر — اس — کے بعد — سات — سخت — سال — آئیں گے — جو — وہ — کھا جائیں گے — جو — تم نے — ان — کے — لیے — ذخیرہ — کیا — سوائے اس — کے — جسے — تم — محفوظ — رکھو۔
۳۔ عملی سبق: مشکلات — کی پیش گوئی — پر — عمل — بہترین حکمت — ہے۔"""
),
1645: (
"پھر — اس کے بعد — ایک سال — آئے گا — جس — میں — لوگوں — پر بارش — بر — ستی — ہے — اور — جس — میں — وہ — رس — نچوڑ — گے",
"""۱۔ ایک — سال — بارش اور نعمت — کی خوشخبری۔
۲۔ ’’ثُمَّ يَأْتِي مِن بَعْدِ ذَٰلِكَ عَامٌ فِيهِ يُغَاثُ النَّاسُ وَفِيهِ يَعْصِرُونَ‘‘ — پھر — اس کے بعد — ایک سال — آئے گا — جس — میں — لوگوں — پر بارش — بر — ستی — ہے — اور — جس — میں — وہ — رس — نچوڑ — گے — یعنی پھر — اس — کے بعد — ایک — سال — آئے گا — جس میں — لوگوں — پر — بارش — بر — ستی — ہے — اور جس میں — وہ — رس — نچوڑ — گے۔
۳۔ عملی سبق: اللہ — تکلیف — کے بعد — خوشحالی — بھی بھیجتا ہے۔"""
),
1646: (
"اور — بادشاہ — نے — کہا — اسے — میرے پاس — لے — آؤ — پس — جب — ایلچی — اس — کے پاس — آیا — انہوں نے — کہا — اپنے رب — کی طرف — واپس جاؤ — اور — اس سے — پوچھو — ان عورتوں — کا کیا حال — ہے — جنہوں نے — اپنے ہاتھ — کاٹے — تھے — بے شک — میرا رب — ان — کی چال — سے باخبر — ہے",
"""۱۔ بادشاہ — یوسفؑ — کو بلواتا ہے — یوسفؑ پہلے — اپنی — براءت — چاہتے ہیں۔
۲۔ ’’وَقَالَ الْمَلِكُ ائْتُونِي بِهِ فَلَمَّا جَاءَهُ الرَّسُولُ قَالَ ارْجِعْ إِلَىٰ رَبِّكَ فَاسْأَلْهُ مَا بَالُ النِّسْوَۃِ اللَّاتِي قَطَّعْنَ أَيْدِيَهُنَّ إِنَّ رَبِّي بِكَيْدِهِنَّ عَلِيمٌ‘‘ — اور — بادشاہ — نے — کہا — اسے — میرے پاس — لے — آؤ — پس — جب — ایلچی — اس — کے پاس — آیا — انہوں نے — کہا — اپنے رب — کی طرف — واپس جاؤ — اور — اس سے — پوچھو — ان عورتوں — کا کیا حال — ہے — جنہوں نے — اپنے ہاتھ — کاٹے — تھے — بے شک — میرا رب — ان — کی چال — سے باخبر — ہے — یعنی بادشاہ — نے کہا — اسے — میرے پاس — لاؤ — پس — جب — ایلچی — اس — کے پاس — آیا — اس نے — کہا — اپنے رب — کی طرف واپس جاؤ — اور — اس سے — پوچھو — ان — عورتوں کا — کیا — حال ہے — جنہوں — نے اپنے — ہاتھ — کاٹے — تھے — بے شک — میرا رب — ان — کی چال — سے باخبر — ہے۔
۳۔ عملی سبق: یوسفؑ — نے اپنی — براءت — پہلے — چاہا؛ حق — کی آواز — بلند رکھو۔"""
),
}
